pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address and the sent amount; the distinguishing rule concerns which sent amounts are accepted.
    function testFuzz_property(address caller, uint256 sendAmount) public {
        // Keep caller non-zero and amount wide but bounded to avoid overflow during vm.deal
        vm.assume(caller != address(0));
        uint256 amount = bound(sendAmount, 0, 20 ether);

        // Ensure caller has funds to send
        vm.deal(caller, amount + 1 ether);

        // Warp time forward to satisfy the timestamp increase requirement relative to default 0
        vm.warp(block.timestamp + 1);

        bool ok;
        // Make the call from the fuzzed caller with the fuzzed amount to the fallback
        vm.prank(caller);
        try c.call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: the reference contract accepts the call iff amount == 10 ether.
        // This single assertTrue reads c.pastBlockTime to ensure the call was successful and state updated
        // when amount == 10 ether; for any other amount the call should revert and pastBlockTime remain 0.
        // Compute expected: if amount == 10 ether the call should succeed and pastBlockTime == block.timestamp,
        // otherwise call reverts and pastBlockTime == 0.

        if (amount == 10 ether) {
            // For the correct contract this must be true for all inputs: call succeeded and state updated
            assertTrue(ok && c.pastBlockTime() == block.timestamp);
        } else {
            // For the correct contract calls with other amounts revert, so ok==false and pastBlockTime stays 0
            assertTrue(!ok && c.pastBlockTime() == 0);
        }
    }
}

