pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: sender address and amount of wei to send
    function testFuzz_property(address sender, uint256 amount) public {
        // Keep sender usable as an EOA
        vm.assume(sender != address(0));

        // Bound amount to a reasonable range that includes 10 ether
        uint256 amt = bound(amount, 0, 100 ether);

        // Ensure sender has funds to send
        vm.deal(sender, amt);

        // Warp time forward so block.timestamp > pastBlockTime (initial default 0)
        vm.warp(block.timestamp + 1);

        bool ok;
        // make the low-level call to trigger fallback; use address(c).call as required
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amt}("");
        ok = success;

        // The universal property we assert: whenever the call used exactly 10 ether, the reference accepts it (ok == true).
        // The mutant requiring 5 ether will reject 10 ether calls, making this assertion fail for some inputs.
        if (amt == 10 ether) {
            assertTrue(ok);
        } else {
            // For other amounts we don't assert acceptance; but to keep a single assertion requirement, assertTrue on a tautology
            // is disallowed; instead we assert that reading public pastBlockTime is consistent with whether the call succeeded.
            // If the call succeeded then pastBlockTime must equal current block.timestamp; if it failed it must remain unchanged (0 or previous).
            // Read c.pastBlockTime() to observe contract state.
            uint256 pb = c.pastBlockTime();
            if (ok) {
                assertTrue(pb == block.timestamp);
            } else {
                // if failed and no prior successful call, pastBlockTime is still 0 (setUp created contract with 0)
                assertTrue(pb != block.timestamp);
            }
        }
    }
}

