pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an actor address and a nonzero block timestamp delta flag
    function testFuzz_property(address actor, uint256 sendAmount) public {
        // admissible domain: sendAmount must equal exactly 10 ether to trigger fallback's require
        vm.assume(actor != address(0));
        // allow fuzzer to provide any uint which we reinterpret; require exact 10 ether for admissible call
        // ensure fuzzer can hit the admissible value
        sendAmount = bound(sendAmount, 0, type(uint256).max);

        // prepare actor with funds and make first call with exactly 10 ether
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // record pastBlockTime after first call
        uint256 t1 = c.pastBlockTime();

        // Do a second call in the SAME block (no vm.warp or vm.roll) which means block.timestamp stays the same.
        // In the correct contract, because block.timestamp == t1, fallback should NOT update pastBlockTime.
        // The mutant (which removed the time check) will update pastBlockTime to the same timestamp again,
        // but since it writes the same value, we need to ensure detection: we rely on the fact that the original
        // contract will not perform the storage write when timestamp not greater. We detect this by observing
        // that the storage write (in mutant) still results in the same numeric value, so to detect mutation
        // we must observe a behavioral side-effect that differs. Instead, we detect whether a second call in the
        // same block returns that pastBlockTime was unchanged (i.e., equals t1) — the correct contract guarantees
        // that no change occurs; the mutant may or may not change the numeric value but will have performed a write.
        // However, because we can only observe the value, we assert the stable general rule: two fallback calls with
        // exactly 10 ether in the same block leave pastBlockTime equal to the original recorded value.

        vm.prank(actor);
        c.fallback{value: 10 ether}();

        uint256 t2 = c.pastBlockTime();

        // exactly one assertion: in the correct contract, t2 == t1 for any actor when both calls are in the same block
        assertTrue(t2 == t1);
    }
}

