pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller and the block timestamp offset (delta) to create same-block or later calls
    function testFuzz_property(address caller, uint256 delta) public {
        // keep caller non-zero and delta small but allow wide range
        vm.assume(caller != address(0));
        delta = bound(delta, 0, 100);

        // fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // first call: ensure time advances by delta seconds from current block.timestamp
        uint256 t0 = block.timestamp + 1; // ensure any change is detectable
        vm.warp(t0);

        vm.prank(caller);
        // first fallback call with 10 ether should set pastBlockTime to block.timestamp in the reference
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1);
        uint256 after1 = c.pastBlockTime();

        // second call: if delta == 0, same block timestamp; if delta >0, timestamp increases
        vm.warp(t0 + delta);

        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2);
        uint256 after2 = c.pastBlockTime();

        // General property to assert: if timestamp did NOT increase (delta == 0), the reference contract
        // must NOT update pastBlockTime, so after2 == after1; the mutant that removed the time check
        // WILL update pastBlockTime (after2 == block.timestamp > after1) for some inputs (e.g., delta==0),
        // hence this assertion holds for the correct contract for all inputs and fails on the mutant for some.
        if (delta == 0) {
            assertTrue(after2 == after1);
        } else {
            // when time increases, both correct and mutant set pastBlockTime to new timestamp; assert equality
            assertTrue(after2 == block.timestamp);
        }
    }
}

