pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an actor and a block number to control whether block.number % 15 == 0
    function testFuzz_property(address payer, uint256 targetBlock) public {
        vm.assume(payer != address(0));
        // keep targetBlock in a reasonable range so vm.roll can be used
        uint256 blk = bound(targetBlock, 1, type(uint64).max);

        // Fund the contract with some initial balance so transfer can drain it when performed
        // Use a deployer/prank to send initial funds
        vm.deal(payer, 100 ether);
        vm.prank(payer);
        // initial funding via a plain call to the contract's fallback: send 10 ether repeatedly to accumulate
        // send 10 ether once to ensure contract has at least 10 ether
        (bool s,) = payable(address(c)).call{value: 10 ether}("");
        require(s);

        // Move to a block where block.number % 15 != 0 to create the distinguishing scenario
        // If blk % 15 == 0, pick blk+1 to ensure non-drain block; otherwise use blk.
        uint256 chosenBlk = blk;
        if (chosenBlk % 15 == 0) chosenBlk = chosenBlk + 1;
        vm.roll(chosenBlk);

        // Ensure timestamp increases relative to pastBlockTime (which starts at 0)
        vm.warp(block.timestamp + 1);

        // Ensure payer has funds to send exactly 10 ether for the tested call
        vm.deal(payer, 100 ether);
        vm.prank(payer);
        // call fallback sending exactly 10 ether, as required by the contract
        (bool ok,) = address(c).call{value: 10 ether}("");
        // call should succeed (both reference and mutant expect msg.value == 10 ether and timestamp > prev)
        require(ok);

        // After the call at a block where block.number % 15 != 0, the correct contract SHOULD NOT have drained its balance.
        // General rule: for any such admissible input (exactly 10 ether and later timestamp), when block.number % 15 != 0,
        // address(c).balance > 0 holds for the reference; the mutant will violate this for some inputs.
        assertTrue(address(c).balance > 0);
    }
}

