pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: caller address and a block number to decide whether block.number % 15 == 0
    function testFuzz_property(address caller, uint256 targetBlock) public {
        // admissible domain: caller must be non-zero
        vm.assume(caller != address(0));

        // ensure we send exactly 10 ether (as required by the contract)
        uint256 sendAmount = 10 ether;

        // prepare caller with funds
        vm.deal(caller, sendAmount);

        // choose a block number to execute at; keep wide but within reasonable bounds
        // bound targetBlock so vm.roll accepts it (block numbers are uint256 but keep within uint64-ish range)
        uint256 br = bound(targetBlock, 1, 1_000_000);

        // ensure timestamp is strictly increasing relative to initial pastBlockTime (which defaults to 0)
        // set timestamp to a positive value
        vm.warp(1000 + br);

        // set the block number to our chosen value
        vm.roll(br);

        // perform the fallback call from the fuzzed caller
        vm.prank(caller);
        c.f{value: sendAmount}();

        // General rule (single assert): For the reference contract, after the call, address(c).balance == 0 iff block.number % 15 == 0 is false
        // But we must express a property that holds for the reference for ALL inputs and is violated by the mutant for some inputs.
        // For the reference C: if (block.number % 15 == 0) then the contract transfers its entire balance out during fallback, leaving balance 0;
        // otherwise it retains the 10 ether paid, leaving balance == 10 ether.
        bool expectedZero = (block.number % 15 == 0);
        if (expectedZero) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == sendAmount);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: caller address and a block number to test; caller must be a funded EOA
    function testFuzz_property(address caller, uint256 targetBlock) public {
        // admissible domains: caller non-zero, targetBlock in a reasonable range
        vm.assume(caller != address(0));
        // keep targetBlock within a wide but bounded range to avoid extremely large numbers
        uint256 blk = bound(targetBlock, 1, type(uint64).max);

        // arrange: fund caller and ensure contract has some initial balance so transfer effect is observable
        vm.deal(caller, 100 ether);
        vm.deal(address(this), 0);

        // ensure increasing timestamps by advancing time
        // set the block timestamp to a known past, then increment before calling
        vm.warp(block.timestamp + 1);

        // advance to the target block number (vm.roll allowed)
        // If target block < current block, wrap around by setting to current+1 to keep monotonicity
        uint256 current = block.number;
        if (blk <= current) {
            blk = current + 1;
        }
        vm.roll(blk);

        // caller will send exactly 10 ether as required by contract
        uint256 sendAmount = 10 ether;

        // ensure caller has funds
        vm.deal(caller, sendAmount + 1 ether);

        // perform the call as the caller (fallback is external payable, so low-level call used)
        vm.prank(caller);
        // call via low-level to trigger fallback; use (bool, ) = address(c).call{value: sendAmount}("");
        // capture success but we only assert on address(c).balance below
        (bool ok, ) = address(c).call{value: sendAmount}("");

        // The universal property (single assertion): for the correct contract, after such a call,
        // address(c).balance == 0 iff block.number % 15 == 0. We assert that when the contract has been
        // invoked as above, if current block number mod 15 == 0 then contract balance is zero; else it's > 0.
        // We express this as a boolean equality and assertTrue on it.

        bool shouldBeDrained = (block.number % 15 == 0);
        bool isDrained = (address(c).balance == 0);

        // exactly one assertion reading c's public surface (address(c).balance)
        assertTrue(isDrained == shouldBeDrained);
    }
}
